<template><div class="shell"><header class="topbar"><button class="back" @click="router.back()">‹</button><strong>会员详情</strong><span></span></header><main class="content page"><section v-if="member" class="profile-card"><div class="avatar large">{{ member.name?.slice(0,1) }}</div><h2>{{ member.name }}</h2><p>{{ member.phone }} · {{ (member.tags && member.tags!=='[]') ? member.tags : '普通会员' }}</p><p class="muted">生日：{{ member.birthday || '-' }}</p><div class="member-metrics"><span>储值余额<b>¥{{ Number(member.balance||0).toFixed(2) }}</b></span><span>积分<b>{{ member.points||0 }}</b></span><span>累计消费<b>¥{{ Number(member.total_consume||0).toFixed(2) }}</b></span></div></section><Panel title="消费记录"><div v-for="r in records" :key="r.consume_id||r.id" class="consume-record"><div class="consume-head"><b>{{ fmtTime(r.consume_time) }}</b><strong>¥{{ Number(r.amount||0).toFixed(2) }}</strong></div><p v-if="r.order_id">订单号：{{ r.order_no || r.order_id }}</p><p v-if="r.order_id">商品：{{ r.items || '商品明细未记录' }}</p><small>支付：{{ r.order_id ? (payLabel(r.pay_method) || '未记录') : consumeLabel(r) }}</small></div><div v-if="!records.length" class="empty">暂无记录</div></Panel><Panel title="加工记录"><div v-for="o in processingOrders" :key="o.processing_order_id" class="rank-row"><span>{{ o.item_name_snapshot }} · {{ Number(o.quantity||1) }}件<small>{{ (o.create_time||'').slice(0,10) }} · 来料 {{ Number(o.old_gold_weight||0).toFixed(3) }}g + 补金 {{ Number(o.store_gold_weight||0).toFixed(3) }}g</small></span><strong>¥{{ Number(o.due_amount||0).toFixed(2) }}</strong><small>{{ ({PENDING:'待加工',PROCESSING:'加工中',COMPLETED:'待取货',PICKED_UP:'已取货'})[o.status] || o.status }}</small></div><div v-if="!processingOrders.length" class="empty">暂无加工记录</div></Panel><div class="action-row"><button class="primary" :disabled="visitBusy" @click="createVisit">{{ visitBusy ? '创建中...' : '发起回访' }}</button><button v-if="isSales" class="outline" @click="openOrder">移动开单</button><button class="outline" @click="dial">拨号</button></div></main></div></template>
<script setup>import {computed,onMounted,ref} from 'vue';import{useRoute,useRouter}from'vue-router';import{api}from'../api/request.js';import{useAuthStore}from'../stores/auth.js';import Panel from '../components/Panel.vue';const route=useRoute(),router=useRouter(),auth=useAuthStore(),member=ref(null),records=ref([]),processingOrders=ref([]),visitBusy=ref(false);const isSales=computed(()=>auth.role==='SALES');onMounted(async()=>{const md=await api.member(route.params.id);member.value=md?.member||md||{};records.value=await api.consume(route.params.id)||[];try{const d=await api.processingOrders({memberId:route.params.id});processingOrders.value=Array.isArray(d)?d:d?.records||[]}catch{processingOrders.value=[]}});const fmtTime=t=>t?String(t).replace('T',' ').slice(0,16):'';const payLabel=m=>{if(!m)return '';if(String(m).includes('COMBINATION'))return '组合支付';return ({CASH:'现金',WECHAT:'微信',ALIPAY:'支付宝',BANK:'银行卡',BALANCE:'储值'})[m]||m};const consumeLabel=r=>r.order_id?('消费'+(payLabel(r.pay_method)?' · '+payLabel(r.pay_method):'')):(Number(r.amount)>=0?'储值充值':'储值扣款');const dial=()=>{if(typeof uni!=='undefined')uni.makePhoneCall({phoneNumber:member.value.phone});else window.location.href=`tel:${member.value.phone}`};async function createVisit(){visitBusy.value=true;try{const plan=new Date();plan.setDate(plan.getDate()+1);const pad=n=>String(n).padStart(2,'0');await api.visitCreateTask({memberId:Number(route.params.id),visitType:'FOLLOW_UP',planTime:`${plan.getFullYear()}-${pad(plan.getMonth()+1)}-${pad(plan.getDate())} 10:00`});alert('回访任务已创建，可在回访任务页跟进')}catch(e){alert(e?.message||'回访任务创建失败')}finally{visitBusy.value=false}}const openOrder=()=>router.push('/sales')</script>
<style scoped>.consume-record{padding:12px 0;border-bottom:1px solid var(--line)}.consume-record:last-child{border-bottom:0}.consume-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.consume-head b{font-size:13px}.consume-head strong{color:var(--gold-deep)}.consume-record p{margin:6px 0 0;color:var(--ink-2);font-size:13px;overflow-wrap:anywhere}.consume-record small{display:block;margin-top:6px;color:var(--ink-3)}</style>
